function UserCell({
  name,
  fallback,
  color = 'tiffany',
  muted = false,
}: {
  name?: string;
  fallback: string;
  color?: ComponentProps<typeof Avatar>['color'];
  muted?: boolean;
}) {
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1.5',
        muted
          ? 'text-grayscale-opacity-500'
          : 'text-grayscale-opacity-800',
      )}
    >
      <Avatar fallback={fallback} size="xs" color={color} />
      {name}
    </span>
  );
}

function CandidateStage({ count = 3 }: { count?: number }) {
  return (
    <ProgressSegments className="gap-1">
      {Array.from({ length: count }).map((_, index) => (
        <ProgressSegment
          key={index}
          className="flex-1"
          data-state="inactive"
        />
      ))}
    </ProgressSegments>
  );
}

